<?php require __DIR__.'/ui.php';role(['admin','gerente']);$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$p->prepare("INSERT INTO automation_rules(name,trigger_event,conditions_json,action_type,action_json,active)VALUES(?,?,?,?,?,1)")->execute([$_POST['name'],$_POST['trigger_event'],$_POST['conditions_json'],$_POST['action_type'],$_POST['action_json']]);go('automations.php');}if(isset($_GET['toggle'])){$p->prepare("UPDATE automation_rules SET active=CASE active WHEN 1 THEN 0 ELSE 1 END WHERE id=?")->execute([(int)$_GET['toggle']]);go('automations.php');}$rows=$p->query("SELECT * FROM automation_rules ORDER BY id DESC")->fetchAll();page_head('Centro de Automações');?>
<div class="grid g2"><div class="card"><h2>Nova regra</h2><form method="post"><?=csrf_field()?><label>Nome</label><input name="name" required><label>QUANDO</label><select name="trigger_event"><option>order_created</option><option>art_approved</option><option>stock_below_min</option><option>delivery_completed</option><option>special_date_soon</option><option>quote_idle</option></select><label>Condições (JSON)</label><textarea name="conditions_json">{}</textarea><label>ENTÃO</label><select name="action_type"><option>create_notification</option><option>move_production</option><option>create_followup</option><option>send_whatsapp</option><option>create_purchase_alert</option></select><label>Configuração da ação (JSON)</label><textarea name="action_json">{}</textarea><button class="primary">Criar automação</button></form></div><div class="card"><h2>Regras</h2><?php foreach($rows as $x):?><div class="ticket"><b><?=e($x['name'])?></b><small><?=e($x['trigger_event'])?> → <?=e($x['action_type'])?></small><a href="?toggle=<?=$x['id']?>"><?=$x['active']?'Desativar':'Ativar'?></a></div><?php endforeach;?></div></div><?php page_foot();?>